import{_ as n,a0 as m,w as s,s as p,ao as o,I as e,a1 as l,A as i,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linux上有哪些好的終端模擬器? | LCTT x X-CMD","titleTemplate":false,"description":"Linux上有哪些好的終端模擬器? | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux上有哪些好的終端模擬器? | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux上有哪些好的終端模擬器? | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/20140529 What is a good terminal emulator on Linux","title":"Linux上有哪些好的終端模擬器?","tag":"201406","desc":""},"relativePath":"201406/20140529 What is a good terminal emulator on Linux.md","filePath":"[post].md"}'),_={name:"201406/20140529 What is a good terminal emulator on Linux.md"};function d(h,a,u,f,x,T){const r=m("Link");return s(),p("div",null,[a[14]||(a[14]=o('<h1 id="linux上有哪些好的終端模擬器" tabindex="-1">Linux上有哪些好的終端模擬器? <a class="header-anchor" href="#linux上有哪些好的終端模擬器" aria-label="Permalink to “Linux上有哪些好的終端模擬器?”">​</a></h1><p>一個好的終端模擬器是一個選擇Linux而不是Windows或Mac的充分理由，任何Linux的資深用户都會同意這點。通過使用shell，用户可以完成在圖形環境下不可能或者太重複的任務。但是終端模擬器的選擇是非常重要的，因為它會成為你使用最多的程序。我會嘗試列出在Linux上好的終端模擬器的清單，從經典的到奇特的，但是它們都是有效率且獨特的。</p><p>如果你認為還有好的終端程序在這裏沒有提到，請在評論區讓我們知道。這裏列出了許多，大多數是值得你瞭解一下。</p><h3 id="_1-gnome-terminal" tabindex="-1">1. Gnome-terminal <a class="header-anchor" href="#_1-gnome-terminal" aria-label="Permalink to “1. Gnome-terminal”">​</a></h3><p><img src="https://farm4.staticflickr.com/3699/14100905190_478812cae2_z.jpg" alt=""></p><p>讓我們先從“經典”終端開始，對於Gnome而言，Gnome-terminal和Gnome一樣經典。它支持多用户配置，標籤，文本大小調整，背景轉換和高度定製。如它名字暗示的那樣，它適用於Gnome環境。</p><h3 id="_2-konsole" tabindex="-1">2. Konsole <a class="header-anchor" href="#_2-konsole" aria-label="Permalink to “2. Konsole”">​</a></h3><p><img src="https://farm3.staticflickr.com/2897/14101006647_ec13565200_z.jpg" alt=""></p><p>同樣大名鼎鼎，Konsole在KDE環境下等同於Gnome-terminal。Konsole額外支持的一點是分割視圖和書籤目錄。</p><h3 id="_3-xfce-terminal" tabindex="-1">3. (Xfce) terminal <a class="header-anchor" href="#_3-xfce-terminal" aria-label="Permalink to “3. (Xfce) terminal”">​</a></h3><p><img src="https://farm3.staticflickr.com/2928/14100857759_fa29cc968e_z.jpg" alt=""></p><p>Xfce用户同樣有他們的Xfce4終端。這個項目的目的是製造一個在外觀上相似Gnome-terminal的產品，但是更少佔用資源需求。它是高端定製化的，雖然沒有用户配置功能或者透明背景。</p><h3 id="_4-lxterminal" tabindex="-1">4. LXTerminal <a class="header-anchor" href="#_4-lxterminal" aria-label="Permalink to “4. LXTerminal”">​</a></h3>',13)),e("p",null,[l(r,{href:"https://www.flickr.com/photos/xmodulo/14100905020/"},{default:i(()=>[...a[0]||(a[0]=[e("img",{src:"https://farm6.staticflickr.com/5569/14100905020_dd2b3e830e_z.jpg",alt:""},null,-1)])]),_:1})]),a[15]||(a[15]=o('<p>其目標是為了成為桌面環境下的最有名的終端，LXTerminal是為LXDE環境設計的。如你所能想到的，它甚至比xfce-terminal更輕量快速，去除了複雜的自定義和高級選項，只保持了標籤功能。</p><h3 id="_5-terminator" tabindex="-1">5. Terminator <a class="header-anchor" href="#_5-terminator" aria-label="Permalink to “5. Terminator”">​</a></h3><p><img src="https://farm4.staticflickr.com/3726/14100980857_1591317b8a_z.jpg" alt=""></p><p>現在讓我們看看終端模擬器中的勞斯萊斯，Terminator是這些終端裏面功能最完備的一款，它包括了標籤、水平和垂直分割視圖、截屏、用户配置、插件、佈局管理。可能還有一些你永遠都用不到的選項。它的缺點是太大和大量的資源消耗，這些就是你付出的代價。</p><h3 id="_6-tilda" tabindex="-1">6. Tilda <a class="header-anchor" href="#_6-tilda" aria-label="Permalink to “6. Tilda”">​</a></h3>',5)),e("p",null,[l(r,{href:"https://www.flickr.com/photos/xmodulo/14284203351/"},{default:i(()=>[...a[1]||(a[1]=[e("img",{src:"https://farm6.staticflickr.com/5585/14284203351_2c25a33cb4_z.jpg",alt:""},null,-1)])]),_:1})]),a[16]||(a[16]=o('<p>這裏還有一款完全不同的一款終端，它稱為“下拉”式。如果你喜歡你的終端總是一鍵可達，也許你會喜歡下面提到的三個特點。首先，Tilda是一個典型的下拉式終端；它不依賴於環境並且非常輕量；你可以設置透明度或者甚至是不同的背景，並且選擇出現在屏幕的那個邊。除去這些，不要期待太複雜的功能，比如標籤或者分割視圖。Tilda只做一件事：在你需要的時候快速顯示出來。</p><h3 id="_7-guake" tabindex="-1">7. Guake <a class="header-anchor" href="#_7-guake" aria-label="Permalink to “7. Guake”">​</a></h3><p><img src="https://farm4.staticflickr.com/3733/14285529772_aa824b5e39_z.jpg" alt=""></p><p>如果喜歡Tilda的方式，而且希望與Gnome結合更緊密，你應該試試Guake。在功能方面，它多多少少與Tilda相似。兩者之間最大的不同是Guake更美觀。</p><h3 id="_8-yakuake" tabindex="-1">8. Yakuake <a class="header-anchor" href="#_8-yakuake" aria-label="Permalink to “8. Yakuake”">​</a></h3>',5)),e("p",null,[l(r,{href:"https://www.flickr.com/photos/xmodulo/14100857589/"},{default:i(()=>[...a[2]||(a[2]=[e("img",{src:"https://farm6.staticflickr.com/5274/14100857589_142fdc4153_z.jpg",alt:""},null,-1)])]),_:1})]),a[17]||(a[17]=o('<p>KDE用户當然也不會被遺忘，他們有Yakuake，它基本上就是KDE環境下的Guake的替代品。它和Quake功能一樣，除了還有標籤化接口和用户配置。</p><h3 id="_9-terra" tabindex="-1">9. Terra <a class="header-anchor" href="#_9-terra" aria-label="Permalink to “9. Terra”">​</a></h3><p><img src="https://farm4.staticflickr.com/3700/14307721343_0e55878bb0_z.jpg" alt=""></p><p>對於既喜歡Terminator，也喜歡下拉式的資深用户而言，我估計Terra是最好的。介於Guake和Terminator之間，Terra在下拉式中支持分割視圖和標籤。</p><h3 id="_10-rxvt" tabindex="-1">10. rxvt <a class="header-anchor" href="#_10-rxvt" aria-label="Permalink to “10. rxvt”">​</a></h3><p><img src="https://farm3.staticflickr.com/2916/14307721303_805fe977ce_o.png" alt=""></p><p>如果你的目標是儘可能的輕量，並且你希望類似xterm，那麼rxvt就是為你設計的。它沒有標籤和自定義，沒有分割視圖，沒有任何東西，要極輕量就用rxvt。如果有時你只需要剛好夠的功能，那麼rxvt就是為你提供的。</p><h3 id="_11-sakura" tabindex="-1">11. Sakura <a class="header-anchor" href="#_11-sakura" aria-label="Permalink to “11. Sakura”">​</a></h3><p><img src="https://farm4.staticflickr.com/3823/14287031834_d8a5ac966f_z.jpg" alt=""></p><p>作為一款並不有名的終端模擬器，Sakura基於GTK但是並不需要完整的Gnome環境。不像rxvt，Sakura有一些額外的功能，像標籤和顏色自定義，但是它嘗試着保持簡單和基本。因此如果你想要一款不針對特定環境的基礎終端，Sakura可能是你想要的。</p><h3 id="_12-terminology" tabindex="-1">12. Terminology <a class="header-anchor" href="#_12-terminology" aria-label="Permalink to “12. Terminology”">​</a></h3><p><img src="https://farm4.staticflickr.com/3706/14264408226_a0223861ae_z.jpg" alt=""></p><p>這裏面最奇異的終端是Terminology。它原本是為Enlightment設計的，它包括了目前我們看到的常規功能，並且還有我之前沒有見過的功能。比如，直接在終端中播放流媒體，以及在文件列表中顯示略縮圖。</p><hr>',14)),e("p",null,[a[4]||(a[4]=t("via: ",-1)),l(r,{href:"http://xmodulo.com/2014/05/good-terminal-emulator-linux.html"},{default:i(()=>[...a[3]||(a[3]=[t("http://xmodulo.com/2014/05/good-terminal-emulator-linux.html",-1)])]),_:1})]),e("p",null,[a[7]||(a[7]=t("譯者：",-1)),l(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[5]||(a[5]=[t("geekpi",-1)])]),_:1}),a[8]||(a[8]=t(" 校對：",-1)),l(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[6]||(a[6]=[t("wxy",-1)])]),_:1})]),e("p",null,[a[11]||(a[11]=t("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[9]||(a[9]=[t("LCTT",-1)])]),_:1}),a[12]||(a[12]=t(" 原創翻譯，",-1)),l(r,{href:"http://linux.cn/"},{default:i(()=>[...a[10]||(a[10]=[t("Linux中國",-1)])]),_:1}),a[13]||(a[13]=t(" 榮譽推出",-1))])])}const b=n(_,[["render",d]]);export{g as __pageData,b as default};
